const steps=[...document.querySelectorAll('[data-step]')],progress=document.querySelector('[data-progress]'),bar=document.querySelector('[data-bar]');function render(){const n=steps.filter(x=>x.checked).length;progress.textContent=n+' / 5';bar.style.width=n*20+'%'}for(const x of steps)x.addEventListener('change',render);document.querySelector('[data-reset]').addEventListener('click',()=>{for(const x of steps)x.checked=false;render()});
